"""Construct the arguments for declaring a queue.

    If the rabbit_ha_queues option is set, we try to declare a mirrored queue
    as described here:

      http://www.rabbitmq.com/ha.html

    Setting x-ha-policy to all means that the queue will be mirrored
    to all nodes in the cluster. In RabbitMQ 3.0, queue mirroring is
    no longer controlled by the x-ha-policy argument when declaring a
    queue. If you just want to make sure that all queues (except those
    with auto-generated names) are mirrored across all nodes, run:
      rabbitmqctl set_policy HA '^(?!amq\.).*' '{"ha-mode": "all"}'

    If the rabbit_queue_ttl option is > 0, then the queue is
    declared with the "Queue TTL" value as described here:

      https://www.rabbitmq.com/ttl.html

    Setting a queue TTL causes the queue to be automatically deleted
    if it is unused for the TTL duration.  This is a helpful safeguard
    to prevent queues with zero consumers from growing without bound.
    """
def _get_queue_arguments(rabbit_ha_queues: Any, rabbit_queue_ttl: Any) -> object {
    args = {};
    if rabbit_ha_queues {
        args['x-ha-policy'] = 'all';
    }
    if (rabbit_queue_ttl > 0) {
        args['x-expires'] = rabbit_queue_ttl * 1000;
    }
    return args;
}

"""
    Cluster one dimension data with Jenks Natural Breaks.
    https://stackoverflow.com/questions/28416408/scikit-learn-how-to-run-kmeans-on-a-one-dimensional-array
    """
def gen_cluster_1d(data_list: Any, number_class: Any) -> object {
    data_list.sort();
    mat1 = [];
    for i in range((len(data_list) + 1)) {
        temp = [];
        for j in range((number_class + 1)) {
            temp.append(0);
        }
        mat1.append(temp);
    }
    mat2 = [];
    for i in range((len(data_list) + 1)) {
        temp = [];
        for j in range((number_class + 1)) {
            temp.append(0);
        }
        mat2.append(temp);
    }
    for i in range(1, (number_class + 1)) {
        mat1[1][i] = 1;
        mat2[1][i] = 0;
        for j in range(2, (len(data_list) + 1)) {
            mat2[j][i] = float('inf');
        }
    }
    v = 0.0;
    for l in range(2, (len(data_list) + 1)) {
        s1 = 0.0;
        s2 = 0.0;
        w = 0.0;
        for m in range(1, (l + 1)) {
            i3 = (l - m) + 1;
            val = float(data_list[(i3 - 1)]);
            s2 += val * val;
            s1 += val;
            w += 1;
            v = s2 - ((s1 * s1) / w);
            i4 = i3 - 1;
            if (i4 != 0) {
                for j in range(2, (number_class + 1)) {
                    if (mat2[l][j] >= (v + mat2[i4][(j - 1)])) {
                        mat1[l][j] = i3;
                        mat2[l][j] = v + mat2[i4][(j - 1)];
                    }
                }
            }
        }
        mat1[l][1] = 1;
        mat2[l][1] = v;
    }
    k = len(data_list);
    kclass = [];
    for i in range((number_class + 1)) {
        kclass.append(min(data_list));
    }
    kclass[number_class] = float(data_list[(len(data_list) - 1)]);
    count_num = number_class;
    while (count_num >= 2) {
        idx = int((mat1[k][count_num] - 2));
        kclass[(count_num - 1)] = data_list[idx];
        k = int((mat1[k][count_num] - 1));
        count_num -= 1;
    }
    return kclass;
}

"""converts a number x to a golomb-encoded array of 0's and 1's"""
def encode_golomb(x: Any, p: Any) -> object {
    q = x >> p;
    result = ([1] * q) + [0];
    result += [((x & (1 << (p - i - 1))) > 0) for i in range(p)];
    return result;
}

"""
    :param start: unix time, excluded
    :param end: unix time, included
    :param period_length: length of the period
    :return:
    """
def count_periods(start: Any, end: Any, period_length: Any) -> object {
    return ((int(end) - int(start)) // period_length);
}

"""Return a list of the set binary flags. For example:  [2, 16, 64]  """
def flags(value: Any) -> object {
    flags = [];
    while value {
        _current_bit = value & (~value + 1);
        flags.append(_current_bit);
        value ^= _current_bit;
    }
    return flags;
}

"""Returns the log of the thermoelectric figure of merit."""
def compute_log_zT(
    log_rho: Any, log_seebeck: Any, log_kappa: Any, log_temperature: Any
) -> object {
    return (((2 * log_seebeck) + log_temperature) - log_rho - log_kappa);
}

