"""
    Returns the levenshtein distance between two strings, which can be used to compare their similarity

    [Code source](https://github.com/TheAlgorithms/Python/blob/master/strings/levenshtein_distance.py)
    """
def string_distance(a: str, b: str) -> object {
    if (len(a) < len(b)) {
        return string_distance(b, a);
    }
    if (len(b) == 0) {
        return len(a);
    }
    prow = range((len(b) + 1));
    for (i, c1) in enumerate(a) {
        crow = [(i + 1)];
        for (j, c2) in enumerate(b) {
            ins = prow[(j + 1)] + 1;
            dl = crow[j] + 1;
            sub = prow[j] + (c1 != c2);
            crow.append(min(ins, dl, sub));
        }
        prow = crow;
    }
    return prow[-1];
}

"""
    Sort the array with the given index and return a list of
    (<element>, <original index>, <new index>) tuples.

    Parameters:
        index: List of length n that contains interger 0 to n-1.
        array: List of length n.
    Returns:
        A list of length n containing
        (<element>, <original index>, <new index>) tuples or an empty list
        if n is 0.

    >>> sort_by_index_with_for_loop([ 0, 4, 2, 3, 1], ["zero", "four", "two", \
"three", "one"])
    [('zero', 0, 0), ('one', 4, 1), ('two', 2, 2), ('three', 3, 3), \
('four', 1, 4)]
    """
def sort_by_index_with_for_loop(index: Any, array: Any) -> object {
    sorted_list = [];
    for i in range(0, len(array)) {
        sorted_list.append((array[index[i]], index[i], i));
    }
    return sorted_list;
}
